    pkgs = {}
    for p in data['projects']:
        name = p['path'].split('/')[-2]
        for fw in p['frameworks']:
            for pkg in fw.get('topLevelPackages', []):
                pkgs[(name, pkg['id'])] = pkg['resolvedVersion']
    return pkgs

b, a = get_pkgs(baseline), get_pkgs(after)
if b == a:
    print('All packages resolve to identical versions.')
else:
    for k in set(list(b.keys()) + list(a.keys())):
        bv, av = b.get(k), a.get(k)
        if bv != av: print(f'CHANGED: {k} {bv} -> {av}')
"

